   1→//! Requirement installation during workflow execution.
   2→//!
   3→//! Handles interactive remediation of requirement gaps found during
   4→//! a workflow run: PATH activation for inactive tools, starting
   5→//! services, and offering to install missing requirements.
   6→
   7→use crate::error::{BivvyError, Result};
   8→use crate::requirements::checker::GapChecker;
   9→use crate::requirements::status::{GapResult, RequirementStatus};
  10→use crate::ui::{Prompt, PromptType, UserInterface};
  11→use std::path::Path;
  12→
  13→/// Mockable dependencies for the installer.
  14→pub struct InstallerContext<'a> {
  15→    /// Run a shell command, returning true on success.
  16→    pub run_command: &'a dyn Fn(&str) -> bool,
  17→    /// Check whether the network is reachable.
  18→    pub check_network: &'a dyn Fn() -> bool,
  19→    /// Prepend a directory to the process PATH.
  20→    pub prepend_path: &'a dyn Fn(&Path),
  21→}
  22→
  23→/// Handle all requirement gaps for a step.
  24→///
  25→/// Returns `Ok(true)` if the step can proceed, `Ok(false)` if
  26→/// it should be skipped, or `Err` with `RequirementMissing`.
  27→pub fn handle_gaps(
  28→    gaps: &[GapResult],
  29→    checker: &mut GapChecker<'_>,
  30→    ui: &mut dyn UserInterface,
  31→    interactive: bool,
  32→    ctx: &InstallerContext<'_>,
  33→) -> Result<bool> {
  34→    if gaps.is_empty() {
  35→        return Ok(true);
  36→    }
  37→
  38→    let mut blocking = Vec::new();
  39→
  40→    for gap in gaps {
  41→        let outcome = if interactive {
  42→            handle_gap_interactive(gap, checker, ui, ctx)
  43→        } else {
  44→            handle_gap_non_interactive(gap, ui)
  45→        };
  46→
  47→        match outcome {
  48→            Outcome::Resolved | Outcome::CanProceed => {}
  49→            Outcome::Skip { reason } => {
  50→                ui.warning(&reason);
  51→                return Ok(false);
  52→            }
  53→            Outcome::Blocked { requirement } => {
  54→                blocking.push(requirement);
  55→            }
  56→        }
  57→    }
  58→
  59→    if blocking.is_empty() {
  60→        Ok(true)
  61→    } else {
  62→        let names: Vec<&str> = blocking.iter().map(|s| s.as_str()).collect();
  63→        Err(BivvyError::RequirementMissing {
  64→            requirement: names.join(", "),
  65→            message: format!(
  66→                "Missing requirements: {}. Run 'bivvy lint' for details.",
  67→                names.join(", ")
  68→            ),
  69→        })
  70→    }
  71→}
  72→
  73→/// Build the default `InstallerContext` for production use.
  74→pub fn default_context() -> InstallerContext<'static> {
  75→    InstallerContext {
  76→        run_command: &|cmd| {
  77→            std::process::Command::new("sh")
  78→                .arg("-c")
  79→                .arg(cmd)
  80→                .status()
  81→                .is_ok_and(|s| s.success())
  82→        },
  83→        check_network: &|| {
  84→            use std::net::TcpStream;
  85→            use std::time::Duration;
  86→            let timeout = Duration::from_secs(2);
  87→            let addr: std::net::SocketAddr = "1.1.1.1:443".parse().unwrap();
  88→            TcpStream::connect_timeout(&addr, timeout).is_ok()
  89→        },
  90→        prepend_path: &|dir| {
  91→            let current = std::env::var("PATH").unwrap_or_default();
  92→            let new_path = format!("{}:{}", dir.display(), current);
  93→            // SAFETY: single-threaded during gap handling
  94→            unsafe { std::env::set_var("PATH", new_path) };
  95→        },
  96→    }
  97→}
  98→
  99→#[derive(Debug, PartialEq)]
 100→enum Outcome {
 101→    Resolved,
 102→    CanProceed,
 103→    Skip { reason: String },
 104→    Blocked { requirement: String },
 105→}
 106→
 107→fn handle_gap_interactive(
 108→    gap: &GapResult,
 109→    checker: &mut GapChecker<'_>,
 110→    ui: &mut dyn UserInterface,
 111→    ctx: &InstallerContext<'_>,
 112→) -> Outcome {
 113→    match &gap.status {
 114→        RequirementStatus::Satisfied => Outcome::Resolved,
 115→        RequirementStatus::Inactive {
 116→            binary_path,
 117→            activation_hint,
 118→            ..
 119→        } => handle_inactive(&gap.requirement, binary_path, activation_hint, checker, ctx),
 120→        RequirementStatus::ServiceDown {
 121→            start_command,
 122→            start_hint,
 123→            ..
 124→        } => handle_service_down(
 125→            &gap.requirement,
 126→            start_command.as_deref(),
 127→            start_hint,
 128→            checker,
 129→            ui,
 130→            ctx,
 131→        ),
 132→        RequirementStatus::Missing {
 133→            install_template,
 134→            install_hint,
 135→        } => handle_missing(
 136→            &gap.requirement,
 137→            install_template.as_deref(),
 138→            install_hint.as_deref(),
 139→            checker,
 140→            ui,
 141→            ctx,
 142→        ),
 143→        RequirementStatus::SystemOnly {
 144→            warning,
 145→            install_template,
 146→            ..
 147→        } => handle_system_only(
 148→            &gap.requirement,
 149→            warning,
 150→            install_template.as_deref(),
 151→            checker,
 152→            ui,
 153→            ctx,
 154→        ),
 155→        RequirementStatus::Unknown => Outcome::Blocked {
 156→            requirement: gap.requirement.clone(),
 157→        },
 158→    }
 159→}
 160→
 161→fn handle_gap_non_interactive(gap: &GapResult, ui: &mut dyn UserInterface) -> Outcome {
 162→    match &gap.status {
 163→        RequirementStatus::Satisfied => Outcome::Resolved,
 164→        RequirementStatus::SystemOnly { warning, .. } => {
 165→            ui.warning(warning);
 166→            Outcome::CanProceed
 167→        }
 168→        RequirementStatus::Inactive {
 169→            manager,
 170→            activation_hint,
 171→            ..
 172→        } => {
 173→            ui.warning(&format!(
 174→                "'{}' found via {} but not activated. {}",
 175→                gap.requirement, manager, activation_hint
 176→            ));
 177→            Outcome::Blocked {
 178→                requirement: gap.requirement.clone(),
 179→            }
 180→        }
 181→        RequirementStatus::ServiceDown { .. }
 182→        | RequirementStatus::Missing { .. }
 183→        | RequirementStatus::Unknown => Outcome::Blocked {
 184→            requirement: gap.requirement.clone(),
 185→        },
 186→    }
 187→}
 188→
 189→// 6A: Inactive — PATH activation
 190→fn handle_inactive(
 191→    requirement: &str,
 192→    binary_path: &Path,
 193→    activation_hint: &str,
 194→    checker: &mut GapChecker<'_>,
 195→    ctx: &InstallerContext<'_>,
 196→) -> Outcome {
 197→    if let Some(parent) = binary_path.parent() {
 198→        (ctx.prepend_path)(parent);
 199→        checker.invalidate(requirement);
 200→        Outcome::Resolved
 201→    } else {
 202→        Outcome::Skip {
 203→            reason: format!("'{}' activation failed. {}", requirement, activation_hint),
 204→        }
 205→    }
 206→}
 207→
 208→// 6B: ServiceDown — offer to start
 209→fn handle_service_down(
 210→    requirement: &str,
 211→    start_command: Option<&str>,
 212→    start_hint: &str,
 213→    checker: &mut GapChecker<'_>,
 214→    ui: &mut dyn UserInterface,
 215→    ctx: &InstallerContext<'_>,
 216→) -> Outcome {
 217→    let Some(cmd) = start_command else {
 218→        return Outcome::Skip {
 219→            reason: format!("Service '{}' is not running. {}", requirement, start_hint),
 220→        };
 221→    };
 222→
 223→    let prompt = Prompt {
 224→        key: format!("start_{}", requirement),
 225→        question: format!("Start {}? ({})", requirement, cmd),
 226→        prompt_type: PromptType::Confirm,
 227→        default: Some("yes".to_string()),
 228→    };
 229→
 230→    let confirmed = ui
 231→        .prompt(&prompt)
 232→        .ok()
 233→        .and_then(|r| r.as_bool())
 234→        .unwrap_or(false);
 235→
 236→    if !confirmed {
 237→        return Outcome::Skip {
 238→            reason: format!("Service '{}' is not running. {}", requirement, start_hint),
 239→        };
 240→    }
 241→
 242→    if (ctx.run_command)(cmd) {
 243→        checker.invalidate(requirement);
 244→        Outcome::Resolved
 245→    } else {
 246→        Outcome::Skip {
 247→            reason: format!("Failed to start '{}'. {}", requirement, start_hint),
 248→        }
 249→    }
 250→}
 251→
 252→// 6C: Missing — install offer
 253→fn handle_missing(
 254→    requirement: &str,
 255→    install_template: Option<&str>,
 256→    install_hint: Option<&str>,
 257→    checker: &mut GapChecker<'_>,
 258→    ui: &mut dyn UserInterface,
 259→    ctx: &InstallerContext<'_>,
 260→) -> Outcome {
 261→    let hint = install_hint.unwrap_or("Install manually");
 262→
 263→    if install_template.is_none() {
 264→        return Outcome::Skip {
 265→            reason: format!("Missing requirement '{}'. {}", requirement, hint),
 266→        };
 267→    }
 268→
 269→    if !(ctx.check_network)() {
 270→        return Outcome::Skip {
 271→            reason: format!(
 272→                "Installation of '{}' requires network access, which isn't available.",
 273→                requirement
 274→            ),
 275→        };
 276→    }
 277→
 278→    match checker.resolve_install_deps(requirement) {
 279→        Ok(deps) => {
 280→            for dep in &deps {
 281→                if dep == requirement {
 282→                    continue;
 283→                }
 284→                let dep_status = checker.check_one(dep);
 285→                if dep_status.is_satisfied() || dep_status.can_proceed() {
 286→                    continue;
 287→                }
 288→                let dep_prompt = Prompt {
 289→                    key: format!("install_{}", dep),
 290→                    question: format!("Install dependency '{}'?", dep),
 291→                    prompt_type: PromptType::Confirm,
 292→                    default: Some("yes".to_string()),
 293→                };
 294→                let confirmed = ui
 295→                    .prompt(&dep_prompt)
 296→                    .ok()
 297→                    .and_then(|r| r.as_bool())
 298→                    .unwrap_or(false);
 299→                if !confirmed {
 300→                    return Outcome::Skip {
 301→                        reason: format!(
 302→                            "Dependency '{}' for '{}' not installed.",
 303→                            dep, requirement
 304→                        ),
 305→                    };
 306→                }
 307→                checker.invalidate(dep);
 308→            }
 309→        }
 310→        Err(e) => {
 311→            ui.warning(&format!(
 312→                "Could not resolve dependencies for '{}': {}",
 313→                requirement, e
 314→            ));
 315→        }
 316→    }
 317→
 318→    let prompt = Prompt {
 319→        key: format!("install_{}", requirement),
 320→        question: format!("Install {}?", requirement),
 321→        prompt_type: PromptType::Confirm,
 322→        default: Some("yes".to_string()),
 323→    };
 324→
 325→    let confirmed = ui
 326→        .prompt(&prompt)
 327→        .ok()
 328→        .and_then(|r| r.as_bool())
 329→        .unwrap_or(false);
 330→
 331→    if !confirmed {
 332→        return Outcome::Skip {
 333→            reason: format!("Missing requirement '{}'. {}", requirement, hint),
 334→        };
 335→    }
 336→
 337→    let install_success = if let Some(hint_cmd) = install_hint {
 338→        (ctx.run_command)(hint_cmd)
 339→    } else {
 340→        false
 341→    };
 342→
 343→    if !install_success {
 344→        return Outcome::Skip {
 345→            reason: format!(
 346→                "Installation of '{}' failed. Check output above.",
 347→                requirement
 348→            ),
 349→        };
 350→    }
 351→
 352→    // Install exited 0 — invalidate cache and verify the tool is now on PATH
 353→    checker.invalidate(requirement);
 354→    let status = checker.check_one(requirement);
 355→
 356→    if status.is_satisfied() {
 357→        Outcome::Resolved
 358→    } else {
 359→        Outcome::Skip {
 360→            reason: format!(
 361→                "Installed '{}' (exit 0) but not found on PATH. May need shell restart.",
 362→                requirement
 363→            ),
 364→        }
 365→    }
 366→}
 367→
 368→// 6D: SystemOnly — warn + optional managed install
 369→fn handle_system_only(
 370→    requirement: &str,
 371→    warning: &str,
 372→    install_template: Option<&str>,
 373→    checker: &mut GapChecker<'_>,
 374→    ui: &mut dyn UserInterface,
 375→    ctx: &InstallerContext<'_>,
 376→) -> Outcome {
 377→    ui.warning(warning);
 378→
 379→    if install_template.is_none() {
 380→        return Outcome::CanProceed;
 381→    }
 382→
 383→    let prompt = Prompt {
 384→        key: format!("managed_install_{}", requirement),
 385→        question: format!("Install a managed version of {}?", requirement),
 386→        prompt_type: PromptType::Confirm,
 387→        default: Some("no".to_string()),
 388→    };
 389→
 390→    let confirmed = ui
 391→        .prompt(&prompt)
 392→        .ok()
 393→        .and_then(|r| r.as_bool())
 394→        .unwrap_or(false);
 395→
 396→    if !confirmed {
 397→        return Outcome::CanProceed;
 398→    }
 399→
 400→    let result = handle_missing(requirement, install_template, None, checker, ui, ctx);
 401→    match result {
 402→        Outcome::Resolved => Outcome::Resolved,
 403→        _ => Outcome::CanProceed,
 404→    }
 405→}
