    #[test]
    fn update_with_content_writes_both() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let mut entry = store
            .store("http:test", "template", "original", 3600)
            .unwrap();

        entry.metadata.etag = Some("\"new-etag\"".to_string());
        entry.metadata.size_bytes = 11;

        store
            .update_with_content(&entry, "new content")
            .unwrap();

        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "new content");

        let loaded = store.load("http:test", "template").unwrap().unwrap();
        assert_eq!(loaded.metadata.etag, Some("\"new-etag\"".to_string()));
        assert_eq!(loaded.metadata.size_bytes, 11);
    }

    #[test]
    fn no_temp_files_remain_after_store() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template", "content", 3600)
            .unwrap();

        let tmp_count = fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .filter(|e| e.path().to_string_lossy().contains(".tmp"))
            .count();

        assert_eq!(tmp_count, 0, "temporary files should be cleaned up");
    }

    #[test]
    fn concurrent_stores_always_produce_valid_state() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let barrier = Arc::new(Barrier::new(10));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let root = root.clone();
                let barrier = Arc::clone(&barrier);
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();
                    let content = format!("content from thread {}", i);
                    store
                        .store("http:shared", "template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(temp.path());
        let entry = store.load("http:shared", "template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        assert!(
            content.starts_with("content from thread "),
            "unexpected content: {content:?}"
        );

        assert_eq!(
            entry.metadata.size_bytes,
            content.len() as u64,
            "metadata size {} != content size {}",
            entry.metadata.size_bytes,
            content.len()
        );
    }

    #[test]
    fn concurrent_reads_during_writes_see_valid_data() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        {
            let store = CacheStore::new(&root);
            store
                .store("http:test", "template", "initial-content", 3600)
                .unwrap();
        }

        let thread_count = 20;
        let barrier = Arc::new(Barrier::new(thread_count));
        let mut handles = vec![];

        for i in 0..10 {
            let root = root.clone();
            let barrier = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                let store = CacheStore::new(&root);
                barrier.wait();
                let content = format!("updated-content-{}", i);
                store
                    .store("http:test", "template", &content, 3600)
                    .unwrap();
            }));
        }

        for _ in 0..10 {
            let root = root.clone();
            let barrier = Arc::clone(&barrier);
            handles.push(thread::spawn(move || {
                let store = CacheStore::new(&root);
                barrier.wait();
                for _ in 0..50 {
                    if let Ok(Some(entry)) = store.load("http:test", "template") {
                        if let Ok(content) = store.read_content(&entry) {
                            assert!(
                                content.starts_with("initial-content")
                                    || content.starts_with("updated-content-"),
                                "corrupt content: {content:?}"
                            );
                        }
                    }
                }
            }));
        }

        for h in handles {
            h.join().unwrap();
        }
    }
}

