//! Cache storage implementation.
//!
//! All writes use atomic temp-file-then-rename and per-entry file locking
//! to prevent corruption when multiple processes access the cache.

use anyhow::{Context, Result};
use fs2::FileExt;
use sha2::{Digest, Sha256};
use std::fs::{self, File, OpenOptions};
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Storage for cached templates.
///
/// Uses atomic writes (write-to-temp-then-rename) and per-entry file
/// locking to prevent corruption from concurrent access.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

impl CacheStore {
    /// Create a new cache store.
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// Get the cache root directory.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Ensure the cache directory exists.
    fn ensure_dir(&self) -> Result<()> {
        fs::create_dir_all(&self.root)
            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
    }

    /// Get the path for storing an entry's content.
    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        let key = format!("{}:{}", source_id, template_name);
        let hash = Sha256::digest(key.as_bytes());
        let hash_str = hex::encode(&hash[..16]);
        self.root.join(hash_str)
    }

    /// Get the metadata file path for an entry.
    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        self.content_path(source_id, template_name)
            .with_extension("meta.json")
    }

    /// Acquire an exclusive lock for a cache entry.
    ///
    /// Returns a [`File`] handle whose lifetime controls the lock.
    /// The lock is released when the handle is dropped.
    fn lock_entry(&self, source_id: &str, template_name: &str) -> Result<File> {
        self.ensure_dir()?;
        let lock_path = self
            .content_path(source_id, template_name)
            .with_extension("lock");
        let file = OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(false)
            .open(&lock_path)
            .with_context(|| format!("Failed to open lock file {:?}", lock_path))?;
        file.lock_exclusive()
            .with_context(|| format!("Failed to lock cache entry {:?}", lock_path))?;
        Ok(file)
    }

    /// Write a file atomically using write-to-temp-then-rename.
    ///
    /// Writes to a PID-stamped temporary file first, then renames to
    /// the final path. This ensures readers never see partial content.
    fn atomic_write_file(path: &Path, content: &[u8]) -> Result<()> {
        let temp_name = format!(
            "{}.{}.tmp",
            path.file_name().unwrap_or_default().to_string_lossy(),
            std::process::id()
        );
        let temp_path = path.with_file_name(temp_name);
        fs::write(&temp_path, content)
            .with_context(|| format!("Failed to write temp file {:?}", temp_path))?;
        fs::rename(&temp_path, path)
            .with_context(|| format!("Failed to rename {:?} to {:?}", temp_path, path))?;
        Ok(())
    }

    /// Write metadata atomically. Caller must hold the entry lock.
    fn write_metadata(&self, entry: &CacheEntry) -> Result<()> {
        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
        let json = serde_json::to_string_pretty(entry)?;
        Self::atomic_write_file(&meta_path, json.as_bytes())
    }

    /// Store content and return a cache entry.
    ///

